-- Units and categories are written once. An item is added and changed, never deleted: archiving
-- sets archived_at. Its base unit cannot change, because stock is counted in it.
GRANT SELECT, INSERT ON public.units, public.item_categories, public.items TO app_runtime;
--> statement-breakpoint
