-- Whoever sells, stores or keeps the books reads items and their units; an owner or an accountant
-- adds and changes them. Recovery and payroll roles have no business with the item list.
CREATE POLICY units_select ON public.units FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson', 'warehouse_manager'));
--> statement-breakpoint
CREATE POLICY units_insert ON public.units FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant')
    AND created_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
