-- ── hand-written: an item's own unit is not one of its other units ──────────────────────────────
-- One base unit is always one base unit, so a conversion row for it could only contradict that.
-- The function runs as whoever writes the row, so it sees only what they may see; a row it
-- cannot find is left for the foreign key to refuse.
CREATE FUNCTION app.refuse_base_unit_conversion() RETURNS trigger
  LANGUAGE plpgsql SET search_path = ''
  AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.items i
    WHERE i.tenant_id = NEW.tenant_id AND i.id = NEW.item_id AND i.base_unit_id = NEW.unit_id
  ) THEN
    RAISE EXCEPTION 'an item''s own unit has no conversion' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.refuse_base_unit_conversion() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER item_units_refuse_base_unit
  BEFORE INSERT ON public.item_units
  FOR EACH ROW EXECUTE FUNCTION app.refuse_base_unit_conversion();
